const D = { energy: .6, scale: 1, density: .55, speed: 1, wind: .55, hue: 62, x: .5, y: .44, style: 'storm', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A grass sea under a supercell. Nothing here is an object: the whole frame is two
// weathers stacked — a rotating storm base with a rain curtain trailing under it, and a
// plain of grass being combed by gusts that run away toward the horizon. The cloud shadow
// crawls across the plain and drags the light with it. Wind never converges, so the piece
// can never reach a steady state and go STATIC. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }   // >>> : a >> fold caps the hash at 0.5
function fr(i){ return hsh((i*7+13)|0, (i*31+5)|0); }
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function fbm4(x,y){ return .48*vn(x,y)+.26*vn(x*2.03+5.1,y*2.03-3.3)+.16*vn(x*4.07-2.7,y*4.07+7.9)+.10*vn(x*8.1+1.3,y*8.1-4.7); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), wnd = cl(P.wind,0,1);
const Hh = ((P.hue%360)+360)%360;
const tt = K.t;
const bp = sty==='blueprint', ink = sty==='ink', dust = sty==='dustbowl', thm = sty==='thermal';

// ---- palette: [h,s,b] HSB. A storm base is DARK and the plain under it is LIT — that
// counter-lit band along the horizon is the whole picture, and it keeps lum mid-key. ----
let cloudD, cloudL, skyGap, grassD, grassL, rainC, groundHaze;
if (ink)       { cloudD=[Hh+160,6,26];  cloudL=[Hh+150,5,72]; skyGap=[Hh+140,4,88]; grassD=[Hh+150,7,34]; grassL=[Hh+145,6,74]; rainC=[Hh+150,5,58]; groundHaze=[Hh+150,4,80]; }
else if (bp)   { cloudD=[212,76,15];    cloudL=[200,50,40];   skyGap=[196,40,54];   grassD=[206,72,17];   grassL=[188,54,74];   rainC=[196,44,44];   groundHaze=[198,46,44]; }
else if (dust) { cloudD=[Hh-24,52,26];  cloudL=[Hh-8,44,66];  skyGap=[Hh-2,36,80];  grassD=[Hh-14,44,30];  grassL=[Hh-4,50,72];  rainC=[Hh-10,38,52];  groundHaze=[Hh-6,34,66]; }
else if (thm)  { cloudD=[250,80,12];    cloudL=[306,60,42];   skyGap=[330,52,58];   grassD=[264,64,18];   grassL=[38,86,86];    rainC=[288,54,38];   groundHaze=[320,46,50]; }
else           { cloudD=[Hh+168,34,17]; cloudL=[Hh+156,20,58]; skyGap=[Hh+30,22,84]; grassD=[Hh+6,46,26];  grassL=[Hh+2,52,72];  rainC=[Hh+164,18,44]; groundHaze=[Hh+20,20,72]; }

const hzn = cl(P.y,.22,.72);          // horizon as a canvas fraction
const hy = hzn*height;

// ---- perpetual advection: the weather moves across the plain and never returns ----
if (S.adv == null) S.adv = 0;
if (S.lt == null || K.t < S.lt) S.lt = K.t;
const dt = cl(K.t - S.lt, 0, .1); S.lt = K.t;
S.adv += dt * P.speed * (.020 + .030*wnd) * (.85 + .15*Math.sin(tt*.037) + K.swell*.10);
const adv = S.adv;
// the storm's own slow translation — incommensurate with adv, so the shadow and the cell
// never re-align and the frame can never repeat
const cellX = P.x + .16*Math.sin(tt*.0163) + .07*Math.sin(tt*.0411+1.3) - adv*.22;
const shadX = cellX + .10 + .09*Math.sin(tt*.0231+.6);

const BW = 208, BH = Math.max(64, Math.round(BW*height/width));
if (!S.g || S.bk !== BW+'x'+BH){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bk = BW+'x'+BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const cD = hsv(cloudD[0], cloudD[1]/100, cloudD[2]/100);
const cL = hsv(cloudL[0], cloudL[1]/100, cloudL[2]/100);
const cG = hsv(skyGap[0], skyGap[1]/100, skyGap[2]/100);
const gD = hsv(grassD[0], grassD[1]/100, grassD[2]/100);
const gL = hsv(grassL[0], grassL[1]/100, grassL[2]/100);
const cR = hsv(rainC[0], rainC[1]/100, rainC[2]/100);
const cH = hsv(groundHaze[0], groundHaze[1]/100, groundHaze[2]/100);

// storm rotation: two incommensurate rates so the mesocyclone never returns to a pose
const rot1 = tt*.038, rot2 = tt*.0917;
const gust = tt*(.5 + wnd*1.6);
const lightB = .74 + .16*Math.sin(tt*.061) + .10*Math.sin(tt*.149+2.1);

for (let j=0;j<BH;j++){
  const ny = (j+.5)/BH;
  for (let i=0;i<BW;i++){
    const nx = (i+.5)/BW;
    let r,g2,b2;
    if (ny < hzn){
      // ================= the cell =================
      const sv = ny/hzn;                                  // 0 top, 1 horizon
      // base sky brightens toward the horizon: the lit gap under the storm base
      const gapK = Math.pow(sv, 2.6);
      r = cD[0]+(cG[0]-cD[0])*gapK*.9; g2 = cD[1]+(cG[1]-cD[1])*gapK*.9; b2 = cD[2]+(cG[2]-cD[2])*gapK*.9;
      // mesocyclone: the field is sampled in a slowly rotating frame about the cell centre,
      // so the striations wrap round and never repeat
      const dx = (nx-cellX)*1.7, dy = (sv-.86)*2.2;
      const rr = Math.sqrt(dx*dx+dy*dy)+1e-4;
      const th = Math.atan2(dy,dx) + rot1*1.6/(0.35+rr) + rot2*.30;
      const wx = Math.cos(th)*rr, wy2 = Math.sin(th)*rr;
      const cf = fbm4(wx*2.6 + adv*1.2, wy2*3.2 - rot2*.5);
      // cloud mass only exists ABOVE the base; the base is a hard-ish shelf
      const shelf = cl((.86 - sv)*3.2 + (cf-.5)*1.1, 0, 1);
      const mass = cl(shelf*(.35+cf*1.25), 0, 1);
      // two-sided: mass darkens the sky AND its sunlit flanks catch light
      r += (cD[0]-r)*mass*.92; g2 += (cD[1]-g2)*mass*.92; b2 += (cD[2]-b2)*mass*.92;
      const lit = Math.pow(cl(cf-.34,0,1),1.5)*mass*(.45+en*1.05)*lightB;
      r += (cL[0]-r)*lit*.85; g2 += (cL[1]-g2)*lit*.85; b2 += (cL[2]-b2)*lit*.85;
      // rain curtain: a translucent veil hanging out of the base, trailing downwind
      const rcx = cellX + .13 + (1-sv)*.10;
      const rw = (.10 + .12*fbm(sv*4 + rot2, 3.1))*(0.6+en*.8);
      const rcurt = cl(1 - Math.abs(nx-rcx)/Math.max(.02,rw), 0, 1)
                  * cl((sv-.42)*3.4, 0, 1)
                  * (.55 + .45*fbm(nx*9 + gust*.35, sv*7 - gust*.9));
      r += (cR[0]-r)*rcurt*.72; g2 += (cR[1]-g2)*rcurt*.72; b2 += (cR[2]-b2)*rcurt*.72;
      // the lit horizon gap: the bright slot of clear sky under the base
      const slot = Math.pow(cl((sv-.80)/.20,0,1), 1.4) * cl(1-rcurt*1.3, 0, 1);
      r += (cG[0]-r)*slot*.80; g2 += (cG[1]-g2)*slot*.80; b2 += (cG[2]-b2)*slot*.80;
    } else {
      // ================= the plain =================
      const dv = (ny-hzn)/Math.max(.04, 1-hzn);           // 0 horizon, 1 underfoot
      // ground-plane perspective: world Z from screen y
      const Z = 1/Math.max(.012, dv*dv*1.5 + .012);
      const X = (nx-.5)*Z*.7;
      const det = cl(1 - Z*.030, .05, 1);                 // far ground loses detail
      // gust fronts: broad bands of bent grass sweeping AWAY over the plain. Bent grass shows
      // its pale underside, so a gust reads as a moving light band — a big, high-contrast,
      // perpetually renewing area element. This is the motion floor.
      const gz = fbm(X*.30 + gust*.10, Z*.22 - gust*.55);
      const gz2 = fbm(X*.62 - gust*.16, Z*.50 - gust*1.15+9.1);
      const gustK = cl((gz-.44)*2.6, 0, 1)*.62 + cl((gz2-.48)*2.9, 0, 1)*.38;
      // grass tufts: high-frequency texture, scale-correct with distance
      const tuft = fbm4(X*7.5, Z*6.2+adv*.15)*det + (1-det)*.5;
      let lum = .30 + tuft*.34 + gustK*(.34+wnd*.30);
      // cloud shadow crawling over the plain, offset from the cell — drags the light with it
      const shd = cl((fbm(X*.20 + shadX*2.2, Z*.15 - adv*.30)-.40)*2.4, 0, 1);
      lum *= 1 - shd*(.42+en*.24);
      // rain shaft darkens the ground under it
      const rsx = .5 + (cellX-.5)*1.9 + .16;
      lum *= 1 - cl(1-Math.abs(nx-rsx)/.16, 0, 1)*.30;
      lum = cl(lum, 0, 1.25);
      r = gD[0]+(gL[0]-gD[0])*lum; g2 = gD[1]+(gL[1]-gD[1])*lum; b2 = gD[2]+(gL[2]-gD[2])*lum;
      // aerial perspective: the plain dissolves into the horizon haze
      const ha = Math.pow(cl(1-dv*2.6, 0, 1), 1.7)*(.72);
      r += (cH[0]-r)*ha; g2 += (cH[1]-g2)*ha; b2 += (cH[2]-b2)*ha;
    }
    const o = 4*(j*BW+i);
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255); px[o+3]=255;
  }
}
g.updatePixels();
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g,0,0,width,height);
pop();

const AL = P.alpha/100;
const dens = cl(P.density,0,1);
const sc = cl(P.scale,.5,2.2);

// ---- near grass: real blades along the bottom edge, bending on the gust. Gives the plain
// a foreground plane and a scale reference; the bend is driven by the same gust field. ----
push();
noStroke();
const NB = Math.round((30 + dens*130));
for (let i=0;i<NB;i++){
  const f1 = fr(i*3+11), f2 = fr(i*3+12), f3 = fr(i*3+13);
  const bx = ((f1*1.18 - .09) + Math.sin(tt*.013+f2*6.28)*.006)*width;
  const depth = f2;                                  // 0 = at the horizon-ish, 1 = right at the lens
  const by = hy + Math.pow(depth,1.6)*(height-hy)*1.06;
  const bh2 = u*(.02 + Math.pow(depth,1.7)*.30)*sc*(.6+f3*.8);
  // the local gust: same incommensurate field as the plain, sampled at the blade
  const lg = fbm(bx/width*2.4 + gust*.10, depth*1.4 - gust*.55);
  const bend = (lg-.45)*(1.5+wnd*3.4) + .30*Math.sin(tt*(1.1+f3*1.7)+f1*6.28)*(.3+wnd);
  const lumb = cl(.22 + (lg-.3)*.7 + depth*.20, 0, 1);
  const cc = [ grassD[0]+(grassL[0]-grassD[0])*lumb,
               grassD[1]+(grassL[1]-grassD[1])*lumb,
               grassD[2]+(grassL[2]-grassD[2])*lumb*(1-depth*.42) ];
  fill(cc[0], cc[1], cc[2], (72+depth*26)*AL);
  beginShape();
  vertex(bx - bh2*.030, by);
  vertex(bx + bh2*.030, by);
  vertex(bx + bend*bh2*.42 + bh2*.012, by - bh2*.72);
  vertex(bx + bend*bh2*.72, by - bh2);
  vertex(bx + bend*bh2*.42 - bh2*.014, by - bh2*.72);
  endShape(CLOSE);
}
pop();

// ---- rain shafts under the base: fine, but hung on the broad curtain already in the buffer
push();
const rsxp = (.5 + (cellX-.5)*1.9 + .16)*width;
stroke(rainC[0], rainC[1], rainC[2], 20*AL);
strokeWeight(Math.max(.5, u*.0012));
const NR = Math.round(10 + dens*40);
for (let i=0;i<NR;i++){
  const f1 = fr(i*5+301), f2 = fr(i*5+302);
  const sx = rsxp + (f1-.5)*width*.30;
  const y0 = hy*(.52+f2*.30);
  const fall = ((tt*(.5+f2*.9)*P.speed + f1) % 1);
  const yA = y0 + fall*(hy-y0)*.9, yB = yA + hy*.16;
  line(sx + (yA-y0)*.10, yA, sx + (yB-y0)*.10, Math.min(hy, yB));
}
pop();

// ---- horizon haze band + drifting virga veils: broad low-alpha area elements ----
push();
noStroke();
for (let i=0;i<6;i++){
  const f1 = fr(i*5+401), f2 = fr(i*5+402);
  const vx = ((f1 + tt*(.004+f2*.009)*P.speed) % 1.4 - .2)*width;
  fill(groundHaze[0], groundHaze[1]*.8, groundHaze[2], (6+en*7)*AL);
  ellipse(vx, hy - height*(.005+f2*.05) + Math.sin(tt*(.07+f1*.13))*height*.006,
          width*(.34+f1*.5), height*(.020+f2*.045));
}
pop();

// ---- a rare, distant bird crossing: the only "object", and it takes minutes ----
push();
noStroke();
const NBird = Math.round(dens*5);
for (let i=0;i<NBird;i++){
  const f1 = fr(i*7+501), f2 = fr(i*7+502);
  const bp2 = ((tt*(.0075+f2*.011)*P.speed + f1) % 1.35) - .175;
  const bxx = bp2*width, byy = hy*(.50+f1*.36) + Math.sin(tt*(.19+f2*.3)+f1*6)*height*.012;
  const bs = u*.006*(.5+f2)*sc;
  const flap = Math.sin(tt*(3.1+f1*1.9)+f2*6.28)*.5;
  fill(cloudD[0], cloudD[1]*.7, cloudD[2]*(.7+f1*.5), 52*AL);
  beginShape();
  vertex(bxx-bs, byy - bs*flap*.7); vertex(bxx, byy); vertex(bxx+bs, byy - bs*flap*.7);
  vertex(bxx, byy + bs*.18);
  endShape(CLOSE);
}
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
drawingContext.globalAlpha = 1;
